function stampInkMask(characterId) {
 const size = 128;
 const mask = document.createElement('canvas');
 mask.width = mask.height = size;
 const ink = mask.getContext('2d');
 let seed = 2166136261;
 for (const letter of String(characterId)) {
  seed = Math.imul(seed ^ letter.charCodeAt(0), 16777619) >>> 0;
 }
 const random = () => {
  seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
  return seed / 4294967296;
 };
 ink.fillRect(0, 0, size, size);
 ink.globalCompositeOperation = 'destination-out';
 // Patchy pressure affects the rim most. The central emblem stays legible.
 for (let i = 0; i < 5; i++) {
  const angle = random() * Math.PI * 2;
  const distance = 39 + random() * 16;
  const x = size / 2 + Math.cos(angle) * distance;
  const y = size / 2 + Math.sin(angle) * distance;
  const radius = 3 + random() * 4;
  ink.beginPath();
  for (let point = 0; point < 12; point++) {
   const direction = angle + point * Math.PI / 6;
   const edge = radius * (.55 + random() * .65);
   ink.lineTo(x + Math.cos(direction) * edge, y + Math.sin(direction) * edge);
  }
  ink.closePath();
  ink.fill();
 }
 for (let i = 0; i < 150; i++) {
  const x = random() * size;
  const y = random() * size;
  const radius = .45 + random() * .7;
  ink.beginPath();
  ink.arc(x, y, radius, 0, Math.PI * 2);
  ink.fill();
 }
 return 'url("' + mask.toDataURL() + '")';
}

